{{ config(materialized = 'ephemeral') }}

-- ZOOMINFO_DEV -> company_relationship: generated by dbt-onboard-source from the approved STTM.
-- SOURCE_UNIQUE_ID: STTM business keys.

with sp_company_relationship as (
    select
        upper(trim(o.ZOOMINFO_ID)) as source_unique_id,
        o.EMPLOYEE_COUNT as account_number,
        o.LOAD_TIMESTAMP as relationship_start_date,
        o.GDP_UPDATED_TS as relationship_end_date,
        o.GDP_INSERTED_TS,
        o.GDP_IS_ACTIVE
    from {{ source('company_relationship_zoominfo_dev_source', 'silver_zoominfo_company') }} as o
    where nullif(upper(trim(o.ZOOMINFO_ID)), '') is not null
    qualify row_number() over (partition by upper(trim(o.ZOOMINFO_ID)) order by o.GDP_UPDATED_TS desc) = 1
),

ref_source_system as (
    {{ m_get_source_system_skey_company('ZOOMINFO_DEV') }}
),

base as (
    select
        o.source_unique_id,
        r.gdp_source_system_skey as ref_gdp_source_system_skey,
        hub.company_core_skey as company_core_skey,
        null as ref_relationship_type_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for REF_RELATIONSHIP_TYPE_SKEY */,
        null as account_name /* TODO: no join path to COMPANY */,
        try_to_number(o.account_number) as account_number,
        null as account_status,
        null as source_account_id,
        o.relationship_start_date::timestamp_ntz as relationship_start_date,
        o.relationship_end_date as relationship_end_date,
        o.GDP_IS_ACTIVE as gdp_is_active,
        o.GDP_INSERTED_TS as gdp_inserted_ts,
        current_user() as gdp_inserted_by,
        o.GDP_UPDATED_TS as gdp_updated_ts,
        current_user() as gdp_updated_by
    from sp_company_relationship as o
    cross join ref_source_system as r
    left join (
        select source_unique_id, company_core_skey
        from {{ ref('company_core') }}
        where gdp_is_active
        qualify row_number() over (partition by source_unique_id order by gdp_inserted_ts desc) = 1
    ) as hub
        on hub.source_unique_id = o.source_unique_id
)

select
    {{ this.schema }}.seq_company_relationship_skey.nextval as company_relationship_skey,
    source_unique_id,
    ref_gdp_source_system_skey,
    company_core_skey,
    ref_relationship_type_skey,
    account_name,
    account_number,
    account_status,
    source_account_id,
    relationship_start_date,
    relationship_end_date,
    {{ m_company_relationship_hkey() }} as company_relationship_hkey,
    gdp_is_active,
    gdp_inserted_ts,
    gdp_inserted_by,
    gdp_updated_ts,
    gdp_updated_by
from base
